218| fn load_csr_index(path: impl AsRef<Path>, ratio: f32) -> io::Result<InvertedIndexRam> {
219|     let csr = Csr::open(path.as_ref())?;
220|     let mut builder = InvertedIndexBuilder::new();
221|     assert!(ratio > 0.0 && ratio <= 1.0);
222|     let count = (csr.len() as f32 * ratio) as usize;
223|     let bar =
224|         ProgressBar::with_draw_target(Some(count as u64), ProgressDrawTarget::stderr_with_hz(12));
225|     for (row, vec) in bar.wrap_iter(csr.iter().take(count).enumerate()) {
226|         builder.add(
227|             row as u32,
228|             vec.map(|v| v.into_remapped())
229|                 .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?,
230|         );
231|     }
232|     bar.finish_and_clear();
233|     Ok(builder.build())
234| }
